def _session_document(profile_dir: str) -> tuple[dict[str, Any], bool]:
    directory = Path(os.path.expandvars(os.path.expanduser(profile_dir)))
    if not directory.is_dir():
        return {}, False
    store = read_store(directory)
    raw = store.get(SESSION_KEY) or ""
    if not raw:
        return {}, True
    try:
        document = json.loads(raw)
    except ValueError:
        return {}, True
    return (dict(document) if isinstance(document, Mapping) else {}), True


def _generations(profile_dir: str, user_email: str) -> list[dict[str, Any]]:
    """Return the successive persisted user documents, oldest first."""
    reading = replay_history(profile_dir, SESSION_KEY)
    rows: list[dict[str, Any]] = []
    for index, entry in enumerate(reading.get("versions") or []):
        text = entry.get("text")
        if not text:
            continue
        try:
            document = json.loads(text)
        except ValueError:
            continue
        if not isinstance(document, Mapping):
            continue
        user = document.get("user") if isinstance(document.get("user"), Mapping) else document
        rows.append({
            "index": index,
            "email": user.get("email") or user.get("user_email") or user_email,
            "saved_routes": [dict(row) for row in (user.get("savedRoutes") or []) if isinstance(row, Mapping)],
            "incident_reports": [dict(row) for row in (user.get("incidentReports") or []) if isinstance(row, Mapping)],
        })
    return rows


